#include <stdexcept>

int estimar(int piezas) {
    if (piezas < 0 || piezas > 10) {
        throw std::invalid_argument{"Cantidad fuera de 0 a 10"};
    }
    if (piezas == 0) { return 0; }
    return 3 + 2 * piezas;
}

int estimacion_doble(int piezas) {
    return 2 * estimar(piezas);
}

int main() {
    int piezas{2};
    int aceptadas{0};
    try {
        int minutos{estimacion_doble(piezas)};
        ++aceptadas;
        std::cout << minutos << ":";
    } catch (const std::invalid_argument& error) {
        std::cout << "Rechazado:";
    }
    std::cout << aceptadas;
    return 0;
}
